namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int DiscountCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents * RatePercent(loyaltyTier) / 100;

    public static int LoyaltyPartCentsFor(int subtotalCents, LoyaltyTier loyaltyTier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(DiscountCentsFor(subtotalCents, loyaltyTier), CapCents);

    private static int RatePercent(LoyaltyTier loyaltyTier) => loyaltyTier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(loyaltyTier), loyaltyTier, null)
    };
}

namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int DiscountCentsFor(string? promoCode, int amountLeftCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(amountLeftCents / 10, Summer10CapCents);
        }

        return 0;
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCentsFor(int payableTotalCents, LoyaltyTier loyaltyTier, bool express) =>
        express
            ? ExpressFeeCents.UnlessPlatinum(loyaltyTier)
            : StandardFeeCents.UnlessMember(payableTotalCents, loyaltyTier);

    private static int UnlessPlatinum(this int feeCents, LoyaltyTier loyaltyTier) =>
        loyaltyTier == LoyaltyTier.Platinum ? 0 : feeCents;

    private static int UnlessMember(this int feeCents, int payableTotalCents, LoyaltyTier loyaltyTier) =>
        loyaltyTier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromCents
            ? 0
            : feeCents;
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateShippingFeeQuery(int PayableTotalCents, LoyaltyTier LoyaltyTier, bool Express = false);

public sealed class CalculateShippingFee
{
    public int Handle(CalculateShippingFeeQuery query) =>
        ShippingFeePolicy.FeeCentsFor(query.PayableTotalCents, query.LoyaltyTier, query.Express);
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record QuoteCheckoutQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode, bool Express);

public sealed record CheckoutQuote(int PayableCents, int ShippingCents, int TotalCents);

public sealed class QuoteCheckout
{
    private readonly CalculateLoyaltyDiscount _discount = new();
    private readonly CalculateShippingFee _shipping = new();

    public CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var discount = _discount.Handle(
            new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode));
        var shippingCents = _shipping.Handle(
            new CalculateShippingFeeQuery(discount.TotalCents, query.LoyaltyTier, query.Express));

        return new CheckoutQuote(discount.TotalCents, shippingCents, discount.TotalCents + shippingCents);
    }
}

